<?php
require_once __DIR__.'/../config/config.php';$u=current_user();if(!$u){header('Location: index.php?booking=1');exit;}
$notice='';if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$name=trim($_POST['name']??'');$phone=trim($_POST['phone']??'');if(mb_strlen($name)<2||mb_strlen($name)>120)$notice='Invalid name';else{$s=$pdo->prepare('UPDATE users SET name=? WHERE id=?');$s->execute([$name,$u['id']]);$s=$pdo->prepare('UPDATE clients SET name=?,phone=? WHERE email=?');$s->execute([$name,$phone,$u['email']]);$notice='Profile updated';$u=current_user();}if(!empty($_POST['new_password'])){$new=$_POST['new_password'];$old=$_POST['old_password']??'';$s=$pdo->prepare('SELECT password_hash FROM users WHERE id=?');$s->execute([$u['id']]);$hash=$s->fetchColumn();if(strlen($new)<10||!password_verify($old,$hash??''))$notice='Current password incorrect or new password too short';else{$pdo->prepare('UPDATE users SET password_hash=? WHERE id=?')->execute([password_hash($new,PASSWORD_DEFAULT),$u['id']]);$notice='Password changed';}}}
$s=$pdo->prepare('SELECT b.* FROM bookings b WHERE b.email=? ORDER BY b.id DESC');$s->execute([$u['email']]);$bookings=$s->fetchAll();$s=$pdo->prepare('SELECT phone FROM clients WHERE email=? LIMIT 1');$s->execute([$u['email']]);$phone=$s->fetchColumn()?:'';
function esc($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
