]))?></span></div><p>📅 <?=esc($b['event_date']?:'Date to be confirmed')?></p><p>📍 <?=esc($b['event_location']?:'Location to be confirmed')?></p><small>Request #<?=intval($b['id'])?></small></article><?php endforeach;?></div><p><a class="acp-dashboard-button" href="index.php?booking=1" data-book-shoot>+ Book another shoot ↗</a></p></section></main><?php require_once __DIR__.'/includes/ui.php';acp_ui();?><script>document.addEventListener("DOMContentLoaded",()=>{const a=document.getElementById("acpAccountLinks"),n=document.getElementById("acpMainNav");if(a&&n)n.appendChild(a);});</script><script src="assets/reference/password-toggle.js" defer></script></body></html>